values
  ((select id from w), 'recall', 'Fill in the missing word: what did God tell Moses to take off at the burning bush?', 'Exodus 3:5', 'He said, ''Don''t come close. Take off your sandals, for the place you are standing on is holy ground.''', 'WEB', 1,
