  ((select id from w), 'recall', 'Fill in the missing word from Yahweh''s instruction about the Passover memorial.', 'Exodus 12:14', '''This day shall be a memorial for you. You shall keep it as a feast to Yahweh. You shall keep it as a feast throughout your generations by an ordinance forever.''', 'WEB', 1,
   '{"type": "recall", "template": "''This day shall be a memorial for you. You shall keep it as a ___ to Yahweh. You shall keep it as a feast throughout your generations by an ordinance forever.''", "answer": "feast"}', false, 3),
  ((select id from w), 'recall', 'Fill in the missing word: what would the blood be for the Israelites on the night of the tenth plague?', 'Exodus 12:12-13', '''For I will go through the land of Egypt in that night, and will strike all the firstborn in the land of Egypt, both man and animal. I will execute judgments against all the gods of Egypt. I am Yahweh. The blood shall be to you for a token on the houses where you are. When I see the blood, I will pass over you, and no plague will be on you to destroy you when I strike the land of Egypt.''', 'WEB', 2,
   '{"type": "recall", "template": "''For I will go through the land of Egypt in that night, and will strike all the firstborn in the land of Egypt, both man and animal. I will execute judgments against all the gods of Egypt. I am Yahweh. The blood shall be to you for a ___ on the houses where you are. When I see the blood, I will pass over you, and no plague will be on you to destroy you when I strike the land of Egypt.''", "answer": "token"}', false, 4),
  ((select id from w), 'recall', 'Fill in the missing word describing who was struck throughout Egypt at midnight.', 'Exodus 12:29-30', 'At midnight, Yahweh struck all the firstborn in the land of Egypt, from the firstborn of Pharaoh who sat on his throne to the firstborn of the captive who was in the dungeon, and all the firstborn of livestock. Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt, for there was not a house where there was not one dead.', 'WEB', 3,
   '{"type": "recall", "template": "At midnight, Yahweh struck all the ___ in the land of Egypt, from the firstborn of Pharaoh who sat on his throne to the firstborn of the captive who was in the dungeon, and all the firstborn of livestock. Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt, for there was not a house where there was not one dead.", "answer": "firstborn"}', true, 5),
  ((select id from w), 'multiple_choice', 'According to Exodus 14:21, what did Yahweh use to divide the sea?', 'Exodus 14:21-22', 'Moses stretched out his hand over the sea, and Yahweh caused the sea to go back by a strong east wind all night, and made the sea dry land, and the waters were divided. The children of Israel went into the middle of the sea on the dry ground; and the waters were a wall to them on their right hand and on their left.', 'WEB', 5,
   '{"type": "multiple_choice", "options": ["A strong east wind", "Moses'' staff alone", "An earthquake", "A pillar of fire"], "correct_index": 0}', true, 6),
  ((select id from w), 'sequence', 'Put these events of the Red Sea crossing in the order they happen in the text.', 'Exodus 14:21-22; 14:30-31', 'Moses stretched out his hand over the sea, and Yahweh caused the sea to go back by a strong east wind all night, and made the sea dry land, and the waters were divided. The children of Israel went into the middle of the sea on the dry ground; and the waters were a wall to them on their right hand and on their left.; Thus Yahweh saved Israel that day out of the hand of the Egyptians... Israel saw the great work which Yahweh did to the Egyptians, and the people feared Yahweh; and they believed in Yahweh and in his servant Moses.', 'WEB', 3,
   '{"type": "sequence", "items": ["Moses stretches out his hand over the sea", "Yahweh drives the sea back with a strong east wind and the waters are divided", "The children of Israel go into the middle of the sea on dry ground, with the waters a wall on their right and left", "Israel is saved and the people believe in Yahweh and in his servant Moses"], "correct_order": [0, 1, 2, 3]}', false, 7),
  ((select id from w), 'recall', 'Fill in the missing word: what would Israel be to God if they kept the covenant?', 'Exodus 19:5-6', '''Now therefore, if you will indeed obey my voice and keep my covenant, then you shall be my own possession from among all peoples; for all the earth is mine; and you shall be to me a kingdom of priests and a holy nation.''', 'WEB', 2,
   '{"type": "recall", "template": "''Now therefore, if you will indeed obey my voice and keep my covenant, then you shall be my own possession from among all peoples; for all the earth is mine; and you shall be to me a kingdom of priests and a holy ___.''", "answer": "nation"}', false, 8),
  ((select id from w), 'recall', 'Fill in the missing word: the people''s response when Moses relayed Yahweh''s covenant proposal.', 'Exodus 19:8', 'All the people answered together, and said, ''All that Yahweh has spoken we will do.''', 'WEB', 1,
   '{"type": "recall", "template": "All the people answered together, and said, ''All that Yahweh has spoken we will ___.''", "answer": "do"}', false, 9),
  ((select id from w), 'multiple_choice', 'Which of these instructions appears in Exodus 20:12-15?', 'Exodus 20:12-15', '''Honor your father and your mother, that your days may be long in the land which Yahweh your God gives you. You shall not murder. You shall not commit adultery. You shall not steal.''', 'WEB', 2,
   '{"type": "multiple_choice", "options": ["Honor your father and your mother", "Remember the Sabbath day to keep it holy", "You shall not covet your neighbor''s house", "You shall make no idols"], "correct_index": 0}', false, 10),
  ((select id from w), 'sequence', 'Put these three quotations in the order they occur in the text.', 'Exodus 3:14; 19:8; 20:2-3', 'God said to Moses, ''I AM WHO I AM,'' and he said, ''You shall tell the children of Israel this: "I AM has sent me to you."''; All the people answered together, and said, ''All that Yahweh has spoken we will do.''; ''I am Yahweh your God, who brought you out of the land of Egypt, out of the house of bondage. You shall have no other gods before me.''', 'WEB', 4,
   '{"type": "sequence", "items": ["“I AM WHO I AM” — God''s self-revelation to Moses (Exodus 3:14)", "“All that Yahweh has spoken we will do.” — the people''s answer at Sinai (Exodus 19:8)", "“I am Yahweh your God, who brought you out of the land of Egypt... You shall have no other gods before me.” — the opening of the Ten Commandments (Exodus 20:2-3)"], "correct_order": [0, 1, 2]}', true, 11),
  ((select id from w), 'recall', 'Fill in the missing word: what did Moses throw and break when he saw the golden calf?', 'Exodus 32:19-20', 'As soon as he came near to the camp, he saw the calf and the dancing. Then Moses'' anger grew hot, and he threw the tablets out of his hands, and broke them beneath the mountain. He took the calf which they had made, and burned it with fire, ground it to powder, and scattered it on the water, and made the children of Israel drink it.', 'WEB', 2,
   '{"type": "recall", "template": "As soon as he came near to the camp, he saw the calf and the dancing. Then Moses'' anger grew hot, and he threw the ___ out of his hands, and broke them beneath the mountain. He took the calf which they had made, and burned it with fire, ground it to powder, and scattered it on the water, and made the children of Israel drink it.", "answer": "tablets"}', true, 12)
;

