insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, answer_key, is_boss_item, sort_order)
values
  ((select id from w), 'recall', 'Fill in the missing word: what did the burnt offering accomplish for the worshiper, per the text?', 'Leviticus 1:3-4', '''If his offering is a burnt offering from the herd, he shall offer a male without defect. He shall offer it at the door of the Tent of Meeting, that he may be accepted before Yahweh. He shall lay his hand on the head of the burnt offering, and it shall be accepted for him to make atonement for him.''', 'WEB', 1,
   '{"type": "recall", "template": "''If his offering is a burnt offering from the herd, he shall offer a male without defect. He shall offer it at the door of the Tent of Meeting, that he may be accepted before Yahweh. He shall lay his hand on the head of the burnt offering, and it shall be accepted for him to make ___ for him.''", "answer": "atonement"}', false, 1),
  ((select id from w), 'recall', 'Fill in the missing word: by reason of what does the blood make atonement, per Leviticus 17:11?', 'Leviticus 17:11', '''For the life of the flesh is in the blood. I have given it to you on the altar to make atonement for your souls; for it is the blood that makes atonement by reason of the life.''', 'WEB', 2,
   '{"type": "recall", "template": "''For the life of the flesh is in the blood. I have given it to you on the altar to make atonement for your souls; for it is the blood that makes atonement by reason of the ___.''", "answer": "life"}', true, 2),
  ((select id from w), 'recall', 'Fill in the missing word: what did Yahweh say he would be, before all the people, after the deaths of Nadab and Abihu?', 'Leviticus 10:1-3', 'Nadab and Abihu, the sons of Aaron, each took his censer, and put fire in it, and laid incense on it, and offered strange fire before Yahweh, which he had not commanded them. Fire came out from before Yahweh, and devoured them, and they died before Yahweh. Then Moses said to Aaron, ''This is what Yahweh spoke of, saying, "I will show myself holy to those who come near me, and before all the people I will be glorified."''', 'WEB', 3,
   '{"type": "recall", "template": "Nadab and Abihu, the sons of Aaron, each took his censer, and put fire in it, and laid incense on it, and offered strange fire before Yahweh, which he had not commanded them. Fire came out from before Yahweh, and devoured them, and they died before Yahweh. Then Moses said to Aaron, ''This is what Yahweh spoke of, saying, \"I will show myself holy to those who come near me, and before all the people I will be ___.\"''", "answer": "glorified"}', true, 3),
  ((select id from w), 'sequence', 'Put these passages in the order they appear in the book of Leviticus.', 'Leviticus 1,17; 10; 16; 19; 25', 'Leviticus 1,17; Leviticus 10; Leviticus 16; Leviticus 19; Leviticus 25', 'WEB', 3,
   '{"type": "sequence", "items": ["Instructions for sacrifice and the meaning of blood in atonement", "Nadab and Abihu offer unauthorized fire and die before Yahweh, who says through Moses that he will show himself holy", "The Day of Atonement ritual for the whole people", "The holiness code, including the command to love your neighbor", "The Year of Jubilee, when land returns and debts are released"], "correct_order": [0, 1, 2, 3, 4]}', true, 4),
  ((select id from w), 'recall', 'Fill in the missing word: what was made for the people on the Day of Atonement, per the text?', 'Leviticus 16:29-30', '''It shall be a statute to you forever: in the seventh month, on the tenth day of the month, you shall afflict your souls, and shall do no kind of work, whether native-born or a stranger who lives as a foreigner among you; for on this day shall atonement be made for you, to cleanse you. You shall be clean from all your sins before Yahweh.''', 'WEB', 2,
   '{"type": "recall", "template": "''It shall be a statute to you forever: in the seventh month, on the tenth day of the month, you shall afflict your souls, and shall do no kind of work, whether native-born or a stranger who lives as a foreigner among you; for on this day shall ___ be made for you, to cleanse you. You shall be clean from all your sins before Yahweh.''", "answer": "atonement"}', false, 5),
  ((select id from w), 'multiple_choice', 'According to Leviticus 16:29, in which month and on which day was the Day of Atonement observed?', 'Leviticus 16:29', '''It shall be a statute to you forever: in the seventh month, on the tenth day of the month, you shall afflict your souls, and shall do no kind of work, whether native-born or a stranger who lives as a foreigner among you; for on this day shall atonement be made for you, to cleanse you. You shall be clean from all your sins before Yahweh.''', 'WEB', 5,
   '{"type": "multiple_choice", "options": ["The seventh month, the tenth day", "The first month, the fourteenth day", "The tenth month, the first day", "The seventh month, the first day"], "correct_index": 0}', false, 6),
  ((select id from w), 'recall', 'Fill in the missing word from the holiness code''s best-known command.', 'Leviticus 19:18', '''You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbor as yourself. I am Yahweh.''', 'WEB', 1,
   '{"type": "recall", "template": "''You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your ___ as yourself. I am Yahweh.''", "answer": "neighbor"}', false, 7),
  ((select id from w), 'multiple_choice', 'According to Leviticus 19:15, how are Israel''s judges instructed to treat the poor and the powerful in judgment?', 'Leviticus 19:15', '''You shall do no injustice in judgment. You shall not be partial to the poor, nor show favoritism to the great; but you shall judge your neighbor in righteousness.''', 'WEB', 2,
   '{"type": "multiple_choice", "options": ["Show no partiality to either — judge in righteousness", "Always favor the poor", "Always favor the powerful", "Let the elders decide case by case"], "correct_index": 0}', false, 8),
  ((select id from w), 'recall', 'Fill in the missing word: what was proclaimed throughout the land in the fiftieth year?', 'Leviticus 25:10', '''You shall make the fiftieth year holy, and proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee to you; and each of you shall return to his own property, and each of you shall return to his family.''', 'WEB', 1,
   '{"type": "recall", "template": "''You shall make the fiftieth year holy, and proclaim ___ throughout the land to all its inhabitants. It shall be a jubilee to you; and each of you shall return to his own property, and each of you shall return to his family.''", "answer": "liberty"}', false, 9),
  ((select id from w), 'recall', 'Fill in the missing word closing Yahweh''s instruction about how to treat the foreigner living among Israel.', 'Leviticus 19:33-34', '''If a stranger lives as a foreigner with you in your land, you shall not do him wrong... you shall love him as yourself; for you lived as foreigners in the land of Egypt. I am Yahweh your God.''', 'WEB', 2,
   '{"type": "recall", "template": "''If a stranger lives as a foreigner with you in your land, you shall not do him wrong... you shall love him as yourself; for you lived as foreigners in the land of Egypt. I am Yahweh your ___.''", "answer": "God"}', false, 10),
  ((select id from w), 'recall', 'Fill in the missing word: whose God does the text say Yahweh is, closing the Jubilee instructions?', 'Leviticus 25:17', '''You shall not wrong one another, but you shall fear your God; for I am Yahweh your God.''', 'WEB', 1,
   '{"type": "recall", "template": "''You shall not wrong one another, but you shall fear your God; for I am Yahweh your ___.''", "answer": "God"}', false, 11)
